// Local heuristic scoring — replace with AI node + UI credential when approved
const KEYWORDS = ['ai', 'llm', 'model', 'agent'];
const out = [];
for (const item of $input.all()) {
  const text = `${item.json.title || ''} ${item.json.contentSnippet || ''}`.toLowerCase();
  const score = KEYWORDS.filter(k => text.includes(k)).length;
  out.push({ json: { ...item.json, score, important: score >= 2 } });
}
console.log(`[ai] scored ${out.length} items`);
return out;
